const path = require("node:path");
const { lstat, realpath, mkdir, open, link, unlink } = require("node:fs/promises");
const { randomUUID } = require("node:crypto");

(async () => {
  const repoRoot = path.resolve(process.cwd());
  const namespace = path.join(repoRoot, "docs", "analysis", "components", "file");
  const target = path.join(namespace, "bin", "csl-agent-kit.js.md");
  const relative = path.relative(namespace, target);
  if (relative === "" || path.isAbsolute(relative) || relative === ".." || relative.startsWith(`..${path.sep}`)) {
    throw new Error("Unsafe active report path.");
  }
  if (await realpath(repoRoot) !== repoRoot) throw new Error("Git root is not canonical.");

  let candidate = "";
  for await (const chunk of process.stdin) candidate += chunk;
  if (!candidate.endsWith("\n")) throw new Error("Candidate must end with a newline.");

  const segments = path.relative(repoRoot, path.dirname(target)).split(path.sep);
  const identities = new Map();
  let current = repoRoot;
  const ensureDirectory = async (directory, allowCreate) => {
    let stat;
    try {
      stat = await lstat(directory);
    } catch (error) {
      if (error.code !== "ENOENT" || !allowCreate) throw error;
      try {
        await mkdir(directory);
      } catch (mkdirError) {
        if (mkdirError.code !== "EEXIST") throw mkdirError;
      }
      stat = await lstat(directory);
    }
    if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error(`Unsafe output parent: ${directory}`);
    return stat;
  };

  identities.set(repoRoot, await ensureDirectory(repoRoot, false));
  for (const segment of segments) {
    current = path.join(current, segment);
    identities.set(current, await ensureDirectory(current, true));
  }
  if (await realpath(namespace) !== namespace) throw new Error("Output namespace is not canonical.");

  try {
    const existing = await lstat(target);
    if (!existing.isFile() || existing.isSymbolicLink()) throw new Error("Active report target is not a regular file.");
    throw new Error("Active report appeared before publication; replacement was not confirmed.");
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }

  const recheckParents = async () => {
    for (const [directory, identity] of identities) {
      const stat = await lstat(directory);
      if (stat.isSymbolicLink() || !stat.isDirectory() || stat.dev !== identity.dev || stat.ino !== identity.ino) {
        throw new Error(`Output parent changed: ${directory}`);
      }
    }
  };

  const temp = path.join(path.dirname(target), `.${path.basename(target)}.${process.pid}.${randomUUID()}.tmp`);
  let handle;
  let owned = false;
  let primaryError;
  try {
    await recheckParents();
    handle = await open(temp, "wx");
    owned = true;
    await handle.writeFile(candidate, "utf8");
    await handle.close();
    handle = undefined;
    await recheckParents();
    await link(temp, target);
    await unlink(temp);
    console.log(target);
  } catch (error) {
    primaryError = error;
    throw error;
  } finally {
    if (handle) {
      try { await handle.close(); } catch (error) { if (!primaryError) throw error; }
    }
    if (owned) {
      try {
        await unlink(temp);
      } catch (error) {
        if (error.code !== "ENOENT") throw error;
      }
    }
  }
})().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
